python3 -c "import os,sys
m='pre-tool-use'
try:
 d=os.getcwd()
 while 1:
  g=os.path.join(d,'.git')
  if os.path.exists(g) and (not os.path.isdir(g) or os.path.exists(os.path.join(g,'HEAD'))):break
  p=os.path.dirname(d)
  if p==d:raise OSError('no git root above '+os.getcwd())
  d=p
 a=os.path.join(d,'gars','_system','codex_hook.py')
 if not os.path.isfile(a):raise OSError('no adapter at '+a)
 os.execv(sys.executable,[sys.executable,a,m])
except BaseException as e:
 if m=='session-start':sys.exit(0)
 print('Blocked: the GARS guard could not start (%s), so it cannot judge this call (R-098; decision 0266). Next: start Codex inside a GARS clone, then retry the call.'%e,file=sys.stderr);sys.exit(2)
"

